CREATE TYPE "rdv_categorie" AS ENUM (
	'Médical',
	'Paramédical',
	'Aide à domicile',
	'Autres',
	'Proches'
);

CREATE TYPE "importance" AS ENUM (
	'faible',
	'moyenne',
	'élevée'
);

CREATE TYPE "lieux" AS ENUM (
	'à domicile',
	'à l''extérieur'
);

CREATE TYPE "role" AS ENUM (
	'admin',
	'invité',
	'proche',
	'intervenant',
    'bénéficiaire'
);

CREATE TABLE IF NOT EXISTS "participer" (
	"personne_id" INTEGER NOT NULL,
	"evenement_id" INTEGER NOT NULL,
	PRIMARY KEY("personne_id", "evenement_id")
);

CREATE TABLE IF NOT EXISTS "categorie" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"nom" VARCHAR(50) NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "message" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"description" TEXT NOT NULL,
	"date" DATE NOT NULL,
	"personne_id" INTEGER NOT NULL,
	"categorie_id" INTEGER NOT NULL,
	"importance" IMPORTANCE NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "personne" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"nom" VARCHAR(50) NOT NULL,
	"prenom" VARCHAR(50) NOT NULL,
	"date_naissance" DATE,
	"mail" VARCHAR(255) NOT NULL,
	"role" ROLE NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "evenement" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"nom" VARCHAR(50) NOT NULL,
	"date_debut" DATE NOT NULL,
	"date_fin" DATE NOT NULL,
	"heure_debut" TIME NOT NULL,
	"heure_fin" TIME NOT NULL,
	"type" RDV_CATEGORIE NOT NULL,
	"lieu" LIEUX NOT NULL,
	"description" VARCHAR(255) NOT NULL,
	"personne_id" INTEGER NOT NULL,
	PRIMARY KEY("id")
);

ALTER TABLE "message"
ADD FOREIGN KEY("personne_id") REFERENCES "personne"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "message"
ADD FOREIGN KEY("categorie_id") REFERENCES "categorie"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "evenement"
ADD FOREIGN KEY("personne_id") REFERENCES "personne"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "participer"
ADD FOREIGN KEY("personne_id") REFERENCES "personne"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "participer"
ADD FOREIGN KEY("evenement_id") REFERENCES "evenement"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;